 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, mix, smoothstep, fract, sin, dot, add, mul, oneMinus, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const root = new THREE.Group();

  root.userData.handlers = {};
  const timelines = [];
  const primitiveCleanups = [];
  let disposed = false;

  const width = 1.6;
  const height = 1.0;
  const geometry = new THREE.PlaneGeometry(width, height, 1, 1);

  const surface = vec3(11 / 255, 11 / 255, 16 / 255);
  const ink = vec3(22 / 255, 22 / 255, 29 / 255);
  const accent = vec3(1.0, 42 / 255, 56 / 255);

  const uvy = uv().y;
  const gradient = mix(surface, ink, smoothstep(0.0, 1.0, uvy));

  const noiseUV = uv().mul(vec2(900.0, 700.0));
  const noiseVal = fract(mul(sin(dot(noiseUV, vec2(12.9898, 78.233))), 43758.5453));
  const grain = noiseVal.mul(0.04);

  const accentHaze = smoothstep(0.08, 0.0, uvy).mul(0.18);
  const baseColor = add(mul(gradient, oneMinus(grain)), mul(accent, accentHaze));

  const cardMat = new MeshBasicNodeMaterial({
    color: 0xffffff,
    side: THREE.DoubleSide
  });
  cardMat.colorNode = baseColor;

  const card = new THREE.Mesh(geometry, cardMat);
  root.add(card);

  let loadedTex = null;
  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;

  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      if (disposed) {
        tex.dispose();
        return;
      }

      loadedTex = tex;
      tex.colorSpace = THREE.SRGBColorSpace;

      const t = texture(tex, uv());
      const composite = mix(baseColor, t.rgb, t.a);
      cardMat.colorNode = composite;
      cardMat.needsUpdate = true;
    });
  }

  const primitives = config.cinematicPrimitives ?? [];
  for (const p of primitives) {
    if (!ctx.primitives[p.name]) continue;

    const result = ctx.primitives[p.name](root, p.params ?? {});
    if (result?.timeline) timelines.push(result.timeline);
    if (result?.cleanup) primitiveCleanups.push(result.cleanup);
  }

  root.userData.cleanup = () => {
    disposed = true;

    timelines.forEach((t) => t?.kill());
    primitiveCleanups.forEach((c) => c?.());

    if (loadedTex) loadedTex.dispose();

    geometry.dispose();
    cardMat.dispose();
  };

  return root;
}
